# Newline-preserving neutraliser (reuses the _UNSAFE class minus \n):
_UNSAFE_KEEPNL = re.compile("[\x00-\x09\x0b-\x1f\x7f-\x9f\u200e\u200f\u202a-\u202e\u2066-\u2069]")

def _safe_nl(s: Any) -> str:
    return _UNSAFE_KEEPNL.sub(lambda m: f"\\x{ord(m[0]):02x}" if ord(m[0]) < 0x100 else f"\\u{ord(m[0]):04x}", str(s))

def log(kind: str, msg: str) -> None:
    msg = _safe_nl(msg)
    if kind == "say":
        print(f"{CYAN}[\uc5d0\uc774\uc804\ud2b8]{RESET} {msg}", flush=True)
    elif kind == "call":
        print(f"{DIM}  \u2192 {msg}{RESET}", flush=True)
    elif kind == "result":
        lines = msg.splitlines()
        head = "\n".join(lines[:6]) + (f"\n\u2026 ({len(lines) - 6}\uc904 \ub354)" if len(lines) > 6 else "")
        print(f"{DIM}{head}{RESET}", flush=True)
